 *    screen reader announces the result. We do NOT also fire the live region
 *    to avoid a double-announcement (focus move is sufficient).
 */

'use strict';

/* ── Field definitions ─────────────────────────────────────────────────── */

/**
 * @typedef {{ id: string, validate: (value: string) => string|null }} FieldDef
 */

/** @type {FieldDef[]} */
const FIELDS = [
  {
    id: 'full-name',
    validate(value) {
      if (!value.trim()) {
        return 'Error: Full name is required.';
      }
      return null;
    },
  },
  {
    id: 'email',
    validate(value) {
      if (!value.trim()) {
        return 'Error: Email address is required.';
      }
      // RFC-lite: must contain exactly one @, a domain, and a TLD
      if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(value.trim())) {
        return 'Error: Enter a valid email address, like name@example.com.';
      }
      return null;
    },
  },
  {
    id: 'phone',
    validate(value) {
      if (!value.trim()) {
        return null; // optional — blank is always valid
      }
      // Accept common North American and international formats:
      //   (555) 555-5555 · 555-555-5555 · +1 555 555 5555 · +44 7911 123456
      if (!/^\+?[\d\s\-().]{7,20}$/.test(value.trim())) {
        return 'Error: Enter a valid phone number. Use the format (555) 555-5555.';
      }
      return null;
    },
  },
];

/* ── DOM references ─────────────────────────────────────────────────────── */

const contactForm     = /** @type {HTMLFormElement}  */ (document.getElementById('contact-form'));
const formPanel       = /** @type {HTMLElement}      */ (document.getElementById('form-panel'));
const successPanel    = /** @type {HTMLElement}      */ (document.getElementById('success-panel'));
const successHeading  = /** @type {HTMLElement}      */ (document.getElementById('success-heading'));
const sendAnotherBtn  = /** @type {HTMLButtonElement}*/ (document.getElementById('send-another-btn'));

/* ── Field helpers ──────────────────────────────────────────────────────── */

/**
 * Retrieve the <input> and its associated error <p> for a given field id.
 * @param {string} id
 * @returns {{ input: HTMLInputElement, errorEl: HTMLElement }}
 */
function getFieldEls(id) {
  return {
    input:   /** @type {HTMLInputElement} */ (document.getElementById(id)),
    errorEl: /** @type {HTMLElement}      */ (document.getElementById(`${id}-error`)),
  };
}

/**
 * Mark a field as invalid: set aria-invalid, add error class, set error text.
 * @param {string} id
 * @param {string} message
 */
function setError(id, message) {
  const { input, errorEl } = getFieldEls(id);
  input.setAttribute('aria-invalid', 'true');
  // Updating textContent on an existing role="alert" element causes AT
  // to announce the new message (live region mutation).
  errorEl.textContent = message;
}

/**
 * Clear invalid state for a field.
 * @param {string} id
 */
function clearError(id) {
  const { input, errorEl } = getFieldEls(id);
  input.removeAttribute('aria-invalid');
  // Clearing text hides the element via the :empty CSS rule.
  errorEl.textContent = '';
}

