FIELDS.forEach((field) => {
  const { input } = getFieldEls(field.id);

  // Validate when the user leaves the field.
  input.addEventListener('blur', () => {
    validateField(field);
  });

  // Re-validate on every keystroke once the field has been marked invalid,
  // so errors clear as soon as the value becomes acceptable.
  input.addEventListener('input', () => {
    if (input.getAttribute('aria-invalid') === 'true') {
