contactForm.addEventListener('submit', (event) => {
  event.preventDefault();

  // Validate every field and collect results.
  const results = FIELDS.map((field) => ({
    id:    field.id,
    valid: validateField(field),
  }));

  const firstInvalid = results.find((r) => !r.valid);

